import {newMatch,legalActions,applyAction,chooseAction,activePlayer} from './rules-engine.mjs';
import {RESOURCES} from './settlement-engine.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function installIslandMatch({getGame,onChange,onReview}){
 const panel=document.createElement('aside');panel.id='island-match-panel';panel.hidden=true;document.querySelector('.workspace').append(panel);
 let state=null,c=null,selected=null,active=false,computer=true,history=[],source=null;
 const api={get active(){return active;},get state(){return state;},get selectedId(){return c?.tiles[selected]?.id??null;},get legalIds(){return state?legalActions(c,state).map(a=>c.tiles[a.cell]?.id).filter(Boolean):[];},get pathIds(){return [];},enter(){c=getGame().runtime;if(source!==JSON.stringify(getGame())){state=null;source=JSON.stringify(getGame());}active=true;panel.hidden=false;document.body.classList.add('guided-play');render();return true;},leave(){active=false;panel.hidden=true;document.body.classList.remove('guided-play');},reset(){api.leave();state=null;source=null;},selectObject(id){selected=c.tiles.findIndex(t=>t.id===id);render();onChange();},projection};
 function act(a){history.push(structuredClone(state));state=applyAction(c,state,a);selected=null;render();onChange();}
 function render(){panel.scrollTop=0;if(!state){panel.innerHTML=`<div class="eyebrow">ISLAND SETTLEMENTS</div><h2>${esc(getGame().name)}</h2><p>Gather resources. Trade with the bank. Build settlements and upgrade cities.</p><ol><li>Production happens on both players’ land.</li><li>Choose one action per turn.</li><li>First to ${c.targetPoints} points wins.</li></ol><label><input id="island-computer" type="checkbox" ${computer?'checked':''}> Play against the local computer</label><p class="match-note">This opponent uses a local heuristic. Astra designs and revises the game.</p><button class="primary" id="island-start">Start island game</button><button id="island-rules">Read the rules</button>`;panel.querySelector('#island-computer').onchange=e=>computer=e.target.checked;panel.querySelector('#island-start').onclick=()=>{state=newMatch(c,1);history=[];render();onChange();};panel.querySelector('#island-rules').onclick=()=>document.getElementById('edit-rules').click();return;}
 const p=activePlayer(c,state),actions=legalActions(c,state),bot=computer&&p===1&&!state.finished;const chosen=actions.filter(a=>a.cell===selected),harvest=actions.filter(a=>a.type==='harvest'),trades=actions.filter(a=>a.type==='trade');
 panel.innerHTML=`<div class="eyebrow">${state.finished?'GAME COMPLETE':`TURN ${state.turn+1} / ${c.turnLimit} · ROLL ${state.roll}`}</div><h2>${esc(state.finished?(state.winner===null?'Shared victory':c.playerNames[state.winner]+' wins'):c.playerNames[p]+'’s turn')}</h2><div class="scoreboard">${c.playerNames.map((name,i)=>`<div class="${i===(state.finished?state.winner:p)?'current':''}"><span>${esc(name)}</span><strong>${state.scores[i]}<small> / ${c.targetPoints}</small></strong></div>`).join('')}</div><div class="island-inventory">${c.playerNames.map((name,i)=>`<h3>${esc(name)} · resources</h3><div>${RESOURCES.map(r=>`<span>${r}<b>${state.resources[i][r]}</b></span>`).join('')}</div>`).join('')}</div>
 ${state.finished?'<p>Play again, review the match with Astra, or print the game.</p>':bot?'<p>The local computer will choose a legal action.</p><button id="island-bot" class="primary">Play computer action</button>':harvest.length?`<p>No production reached you. Choose one resource, then take your action.</p><div class="island-harvest">${harvest.map(a=>`<button data-harvest="${a.resource}">Take ${a.resource}</button>`).join('')}</div>`:`<p>Select a hex to build or upgrade. Trading uses this turn’s action.</p><label for="island-space">Choose a hex</label><select id="island-space"><option value="">Select on board or here</option>${c.tiles.map((t,i)=>`<option value="${i}" ${i===selected?'selected':''}>${i+1}. ${esc(t.resource)} · ${t.number}${state.owners[i]===null?'':` · ${esc(c.playerNames[state.owners[i]])}`}</option>`).join('')}</select>${chosen.map((a,i)=>`<button class="primary" data-build="${i}">${a.type==='build'?'Build · 1 wood, 1 brick, 1 grain':'City · 2 grain, 2 ore'}</button>`).join('')}${selected!==null&&selected>=0&&!chosen.length?'<p class="match-note">No affordable legal build here. Choose a highlighted hex, trade, or pass.</p>':''}<details><summary>Bank trade · 3 for 1</summary><div class="island-trades">${trades.map((a,i)=>`<button data-trade="${i}">3 ${a.give} → 1 ${a.receive}</button>`).join('')||'<p>You need three matching resources to trade.</p>'}</div></details><button id="island-pass">Pass turn</button>`}
 <details class="match-log" open><summary>What happened</summary><ol>${state.log.slice(-5).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></details>${state.finished?'<button class="primary" id="island-review">Review this match with Astra</button><button id="island-export">Save match record</button>':''}<button id="island-undo" ${history.length?'':'disabled'}>Undo action</button><button id="island-restart">New match</button><button id="island-rules">Rules</button>`;
 panel.querySelector('#island-space')?.addEventListener('change',e=>api.selectObject(e.target.value===''?null:c.tiles[Number(e.target.value)]?.id));panel.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>act(chosen[Number(b.dataset.build)]));panel.querySelectorAll('[data-harvest]').forEach(b=>b.onclick=()=>act({type:'harvest',resource:b.dataset.harvest}));panel.querySelectorAll('[data-trade]').forEach(b=>b.onclick=()=>act(trades[Number(b.dataset.trade)]));panel.querySelector('#island-pass')?.addEventListener('click',()=>act({type:'pass'}));panel.querySelector('#island-bot')?.addEventListener('click',()=>act(chooseAction(c,state)));panel.querySelector('#island-undo').onclick=()=>{state=history.pop();selected=null;render();onChange();};panel.querySelector('#island-restart').onclick=()=>{state=null;history=[];render();onChange();};panel.querySelector('#island-rules').onclick=()=>document.getElementById('edit-rules').click();panel.querySelector('#island-export')?.addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({format:'board-studio-match',version:1,game:getGame(),state},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='board-studio-island-match.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});panel.querySelector('#island-review')?.addEventListener('click',()=>onReview({seed:state.seed,scores:state.scores,turns:state.turn,log:state.log,opponent:computer?'local heuristic':'two people'}));
 }
 function projection(){if(!active)return null;const g=structuredClone(getGame());if(!state)return g;const find=id=>g.objects.find(o=>o.id===id);c.tiles.forEach((t,i)=>{if(state.owners[i]===null)return;const p=state.owners[i],tile=find(t.id),o=structuredClone(find(c.pawnIds[p]));o.id='match-building-'+i;o.name=c.playerNames[p]+' '+(state.levels[i]===2?'city':'settlement');o.x=tile.x;o.z=tile.z+.4;o.width*=.75;o.depth*=.75;o.parts.forEach(part=>{part.x*=.75;part.z*=.75;part.width*=.75;part.depth*=.75;});if(state.levels[i]===2){o.height*=1.35;o.parts.forEach(part=>{part.y*=1.35;part.height*=1.35;});}g.objects.push(o);});g.objects=g.objects.filter(o=>!c.pawnIds.includes(o.id));for(const [i,road] of state.roads.entries()){const a=find(c.tiles[road.from].id),b=find(c.tiles[road.to].id);g.objects.push({id:'match-road-'+i,type:'piece',name:'Road',shape:'square',x:(a.x+b.x)/2,z:(a.z+b.z)/2,width:.12,depth:Math.hypot(b.x-a.x,b.z-a.z),height:.06,rotation:Math.atan2(b.x-a.x,b.z-a.z)*180/Math.PI,color:c.playerColors[road.owner],parts:[],properties:[],text:'',deckId:null,drawn:false,order:0});}return g;}
 return api;
}
